export function reduceMcpAction(
  state: TuiState,
  action: { type: string },
): TuiState | null {
  if (!isMcpAction(action)) return null;
  const panel = state.mcpPanel;
  const next = reducePanel(panel, action);
  if (next === panel) return state;
  return { ...state, mcpPanel: next };
}

